   147  static void test_utf8_parse()
   148  {
   149          // json_tokener_parse doesn't support checking for byte order marks.
   150          // It's the responsibility of the caller to detect and skip a BOM.
   151          // Both of these checks return null.
   152          char* utf8_bom = "\xEF\xBB\xBF";
   153          char* utf8_bom_and_chars = "\xEF\xBB\xBF{}";
   154          single_basic_parse(utf8_bom, 0);
   155          single_basic_parse(utf8_bom_and_chars, 0);
   156  }
